And in `_verify_epoch()`:

<<<<
    def _verify_epoch(self, epoch: dict) -> tuple[bool, str]:
        """Verify a stored epoch's Merkle root against the chain records."""
        record_count = epoch.get("record_count", 0)
        if record_count < 1:
            return False, "epoch record_count must be >= 1"
        if record_count > len(self._records):
            return False, (
                f"epoch claims {record_count} records but chain has "
                f"{len(self._records)}"
            )
        leaves = [
            _digest_bytes(r["chain_hash"])
            for r in self._records[:record_count]
        ]
        expected_root = "sha256:" + rfc9162_merkle_root(leaves).hex()
        stored_root = epoch.get("merkle_root", "")
        if stored_root != expected_root:
            return False, (
                f"merkle_root mismatch: stored {stored_root}, "
                f"computed {expected_root}"
            )
        return True, "OK"
====
    def _verify_epoch(
        self,
        epoch: dict,
        prev_epoch_hash: Optional[str] = None,
    ) -> tuple[bool, str]:
        """Verify a stored epoch's Merkle root and epoch-chain linkage."""
        record_count = epoch.get("record_count", 0)
        if record_count < 1:
            return False, "epoch record_count must be >= 1"
        if record_count > len(self._records):
            return False, (
                f"epoch claims {record_count} records but chain has "
                f"{len(self._records)}"
            )
        leaves = [
            _digest_bytes(r["chain_hash"])
            for r in self._records[:record_count]
        ]
        expected_root = "sha256:" + rfc9162_merkle_root(leaves).hex()
        stored_root = epoch.get("merkle_root", "")
        if stored_root != expected_root:
            return False, (
                f"merkle_root mismatch: stored {stored_root}, "
                f"computed {expected_root}"
            )

        expected_prev = prev_epoch_hash or f"sha256:{GENESIS_CONSTANT}"
        if epoch.get("prev_epoch_hash") != expected_prev:
            return False, (
                f"prev_epoch_hash mismatch: stored {epoch.get('prev_epoch_hash')}, "
                f"expected {expected_prev}"
            )

        epoch_body = {
            "epoch_index": epoch.get("epoch_index"),
            "record_count": epoch.get("record_count"),
            "merkle_root": epoch.get("merkle_root"),
            "sealed_at": epoch.get("sealed_at"),
        }
        expected_epoch_hash = _compute_chain_hash(
            expected_prev,
            sha256_digest(canonical_json(epoch_body).encode("utf-8")),
        )
        if epoch.get("epoch_hash") != expected_epoch_hash:
            return False, (
                f"epoch_hash mismatch: stored {epoch.get('epoch_hash')}, "
                f"computed {expected_epoch_hash}"
            )
        return True, "OK"
